package config

import (
	"context"
	"os"
	"path/filepath"
	"testing"

	"github.com/0xJacky/Nginx-UI/internal/site"
	"github.com/0xJacky/Nginx-UI/internal/testdb"
	"github.com/0xJacky/Nginx-UI/model"
	"github.com/0xJacky/Nginx-UI/query"
	mcpgo "github.com/mark3labs/mcp-go/mcp"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
	"gorm.io/driver/sqlite"
	"gorm.io/gorm"
)

// MCP tools never force a change to a site generated by an ingress.
func TestNginxConfigToolsRefuseManagedSiteFile(t *testing.T) {
	setupMCPConfigValidationTest(t)
	db, err := gorm.Open(sqlite.Open(testdb.DSN(t)), &gorm.Config{})
	require.NoError(t, err)
	require.NoError(t, db.AutoMigrate(&model.Site{}, &model.Config{}, &model.ConfigBackup{}, &model.LLMSession{}))
	model.Use(db)
	query.SetDefault(db)

	path, err := site.ResolveAvailablePath("ingress-web")
	require.NoError(t, err)
	original := "server { listen 80; }\n"
	require.NoError(t, os.MkdirAll(filepath.Dir(path), 0o755))
	require.NoError(t, os.WriteFile(path, []byte(original), 0o644))
	require.NoError(t, db.Create(&model.Site{Path: path, ManagedBy: "ingress:web"}).Error)

	_, err = handleNginxConfigModify(context.Background(), mcpgo.CallToolRequest{
		Params: mcpgo.CallToolParams{Arguments: map[string]any{
			"relative_path": "sites-available/ingress-web",
			"content":       "server { listen 8080; }\n",
		}},
	})
	assert.True(t, site.IsManagedByIngress(err), "modify: want ErrSiteManagedByIngress, got %v", err)

	_, err = handleNginxConfigRename(context.Background(), mcpgo.CallToolRequest{
		Params: mcpgo.CallToolParams{Arguments: map[string]any{
			"base_path": "sites-available",
			"orig_name": "ingress-web",
			"new_name":  "renamed",
		}},
	})
	assert.True(t, site.IsManagedByIngress(err), "rename: want ErrSiteManagedByIngress, got %v", err)

	content, err := os.ReadFile(path)
	require.NoError(t, err)
	assert.Equal(t, original, string(content))
}
